    // 操作错误
    else {
      Message.error(success.data.message);
      return success.data;
    }
  } else {
    Message.error("响应错误");
  }
});

// get请求
export function get(url, params = {}) {
  return new Promise((resolve, reject) => {
    service
      .get(url, { params: params })
      .then((res) => {
        console.log(res, url);
        resolve(res);
      })
      .catch((err) => {
        reject(err);
      });
  });
}

// post请求  管理后台
export function post(url, data = {}) {
  console.log(data);
  return new Promise((resolve, reject) => {
    service
      .post(url, data)
      .then((res) => {
        console.log(res);
        resolve(res);
      })
      .catch((err) => {
        console.log(err);
        Message.error("您的登录信息已过期");
        router.push("/Login");
        reject(err);
      });
  });
}
